import{describe,it,expect}from"vitest";import{ancientCitiesData,getCityById,filterCities,compareBeforeVsToday}from"../../frontend/ancient-cities/ancient-cities.js";const MANDATORY_CITIES=["dholavira","lothal","pataliputra","vijayanagara","taxila","fatehpur-sikri"];describe("Ancient Cities Dataset Coverage & Mandatory Inclusion",()=>{it("contains at least 6 ancient cities",()=>{expect(ancientCitiesData.length).toBeGreaterThanOrEqual(6)}),it("includes all mandatory cities from issue description",()=>{const e=ancientCitiesData.map(e=>e.id.toLowerCase());MANDATORY_CITIES.forEach(t=>{expect(e).toContain(t)})})}),describe("Archaeological Discoveries & Excavation Facts Integrity",()=>{it("every city contains valid archaeological discoveries and excavation facts",()=>{ancientCitiesData.forEach((e,t)=>{expect(e,`City at index ${t} missing id`).toHaveProperty("id"),expect(e,`City at index ${t} missing name`).toHaveProperty("name"),expect(e,`City at index ${t} missing civilization`).toHaveProperty("civilization"),expect(e,`City at index ${t} missing eraPeriod`).toHaveProperty("eraPeriod"),expect(e,`City at index ${t} missing location`).toHaveProperty("location"),expect(e,`City at index ${t} missing mapCoords`).toHaveProperty("mapCoords"),expect(e,`City at index ${t} missing archaeologicalDiscoveries`).toHaveProperty("archaeologicalDiscoveries"),expect(e,`City at index ${t} missing excavationFacts`).toHaveProperty("excavationFacts"),expect(e,`City at index ${t} missing beforeVsToday`).toHaveProperty("beforeVsToday"),expect(Array.isArray(e.archaeologicalDiscoveries)).toBe(!0),expect(e.archaeologicalDiscoveries.length).toBeGreaterThanOrEqual(3),expect(e.excavationFacts).toHaveProperty("discoveredBy"),expect(e.excavationFacts).toHaveProperty("keyExcavator"),expect(e.excavationFacts).toHaveProperty("status"),expect(e.excavationFacts).toHaveProperty("historicalSignificance")})}),it("all city IDs are unique",()=>{const e=ancientCitiesData.map(e=>e.id);expect(new Set(e).size).toBe(e.length)})}),describe("Before vs Today Comparison Engine",()=>{it("generates valid Before vs Today comparison data for Dholavira and Lothal",()=>{const e=compareBeforeVsToday("dholavira");expect(e).toBeDefined(),expect(e.cityName).toBe("Dholavira"),expect(e.before).toContain("Citadel"),expect(e.today).toContain("reservoirs");const t=compareBeforeVsToday("lothal");expect(t).toBeDefined(),expect(t.cityName).toBe("Lothal"),expect(t.before).toContain("dockyard"),expect(t.today).toContain("Museum")}),it("returns null when comparing invalid city ID",()=>{expect(compareBeforeVsToday("invalid-city-xyz")).toBeNull()})}),describe("City Query & Search Filters",()=>{it("retrieves city profile by ID or partial name",()=>{const e=getCityById("vijayanagara");expect(e).toBeDefined(),expect(e.name).toContain("Vijayanagara");const t=getCityById("Taxila");expect(t).toBeDefined(),expect(t.id).toBe("taxila")}),it("filters ancient cities by search query (e.g. Ashoka, Dockyard, or Reservoir)",()=>{const e=filterCities("Ashoka");expect(e.length).toBeGreaterThan(0),expect(e.some(e=>e.name.includes("Pataliputra")||e.name.includes("Taxila"))).toBe(!0);const t=filterCities("Dockyard");expect(t.length).toBeGreaterThan(0),expect(t[0].id).toBe("lothal")}),it("filters cities by region or civilization tag",()=>{const e=filterCities("","harappan");expect(e.length).toBeGreaterThanOrEqual(2);const t=filterCities("","south");expect(t.length).toBeGreaterThan(0)}),it("returns empty array when search query matches nothing",()=>{const e=filterCities("NonExistentCityXYZ");expect(e).toEqual([])})});